// The only way into the `feedback` (requests) table: validates input,
// rate-limits per phone/email, writes with the service role key, then sends the citizen an
// acknowledgement (SMS and/or email) containing their reference number.
// The reference number itself is generated by a DB trigger
// (see migration_nwsc_02_requests.sql).
//
// Deploy: supabase functions deploy submit-feedback
// Secrets: the notification secrets in _shared/notify.ts

import { CORS_HEADERS, json } from '../_shared/cors.ts';
import { isRateLimited } from '../_shared/ratelimit.ts';
import { sendSms, sendEmail, escapeHtml, normalizeUgPhone } from '../_shared/notify.ts';

const REQUEST_TYPES = ['Enquiry', 'Complaint', 'Suggestion', 'Compliment'];
// How the request reached NWSC. Anything but 'Online' is logged by staff on
// behalf of a customer (phone call, walk-in, community meeting…).
const SOURCES = ['Online', 'Phone call', 'Walk-in', 'Community meeting', 'Field visit', 'Letter', 'Social media'];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// If the caller is signed in, link the request to their account so it shows
// under "My requests". Anonymous submissions are still allowed.
async function getCallerId(req: Request, supabaseUrl: string, serviceKey: string): Promise<string | null> {
  const auth = req.headers.get('Authorization');
  if (!auth?.startsWith('Bearer ')) return null;
  try {
    const res = await fetch(`${supabaseUrl}/auth/v1/user`, { headers: { apikey: serviceKey, Authorization: auth } });
    if (!res.ok) return null;
    const user = await res.json();
    return user?.id ?? null;
  } catch {
    return null;
  }
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS_HEADERS });

  try {
    const {
      request_type = 'Complaint', title, description, category, image_url,
      latitude, longitude, location_text, contact_name, contact_phone, contact_email, language,
      source = 'Online',
    } = await req.json();
    if (!SOURCES.includes(source)) return json({ error: 'Invalid source.' }, 400);
    const lang = ['en', 'lg', 'xog'].includes(language) ? language : 'en';

    if (!title || !String(title).trim()) return json({ error: 'Title is required.' }, 400);
    if (!REQUEST_TYPES.includes(request_type)) return json({ error: 'Invalid request type.' }, 400);

    const phone = contact_phone ? String(contact_phone).trim() : '';
    const email = contact_email ? String(contact_email).trim() : '';
    if (!phone && !email) return json({ error: 'Please give a phone number or email so we can update you.' }, 400);
    if (phone && !normalizeUgPhone(phone)) return json({ error: 'Please enter a valid phone number, e.g. 0772 123456.' }, 400);
    if (email && !EMAIL_RE.test(email)) return json({ error: 'Please enter a valid email address.' }, 400);

    if (await isRateLimited('feedback', [['contact_phone', phone], ['contact_email', email]], 5, 60)) {
      return json({ error: 'Too many submissions from this contact in the last hour. Please try again later or call 0800-200-977.' }, 429);
    }

    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const userId = await getCallerId(req, supabaseUrl, serviceRoleKey);

    // Only active staff may log a request received offline.
    let loggedBy: string | null = null;
    if (source !== 'Online') {
      const p = userId
        ? await fetch(`${supabaseUrl}/rest/v1/users?id=eq.${userId}&select=role,is_active`, {
          headers: { apikey: serviceRoleKey, Authorization: `Bearer ${serviceRoleKey}` },
        }).then((r) => (r.ok ? r.json() : []))
        : [];
      if (!p[0] || !['officer', 'supervisor', 'admin'].includes(p[0].role) || p[0].is_active === false) {
        return json({ error: 'Only NWSC staff can log requests received by phone or in person.' }, 403);
      }
      loggedBy = userId;
    }

    const insertRes = await fetch(`${supabaseUrl}/rest/v1/feedback?select=id,reference_no`, {
      method: 'POST',
      headers: {
        apikey: serviceRoleKey,
        Authorization: `Bearer ${serviceRoleKey}`,
        'Content-Type': 'application/json',
        Prefer: 'return=representation',
      },
      body: JSON.stringify({
        request_type,
        title: String(title).trim().slice(0, 200),
        description: description ? String(description).trim().slice(0, 2000) : null,
        category: category || 'General',
        image_url: image_url || null,
        latitude: latitude ?? null,
        longitude: longitude ?? null,
        location_text: location_text ? String(location_text).trim().slice(0, 200) : null,
        contact_name: contact_name ? String(contact_name).trim().slice(0, 120) : null,
        contact_phone: phone || null,
        contact_email: email || null,
        status: 'Submitted',
        // A request logged by staff belongs to the customer, not the officer.
        user_id: loggedBy ? 'anonymous' : userId ?? 'anonymous',
        language: lang,
        source,
        logged_by: loggedBy,
      }),
    });

    if (!insertRes.ok) {
      console.error('[submit-feedback] insert failed:', await insertRes.text());
      return json({ error: 'Could not save your request. Please try again.' }, 500);
    }
    const [row] = await insertRes.json();
    const ref: string = row.reference_no;

    // Acknowledgement — never fails the submission itself.
    const kind = String(request_type).toLowerCase();
    const short = String(title).trim().slice(0, 60);
    // Acknowledgement in the citizen's language (Luganda/Lusoga to be reviewed by native speakers).
    const SMS_TEXT: Record<string, string> = {
      en: `NWSC: We have received your ${kind} "${short}". Ref: ${ref}. Track it on the NWSC e-Participation portal. Emergencies: 0800200977.`,
      lg: `NWSC: Tufunye obubaka bwo "${short}". Ennamba: ${ref}. Bugoberere ku mukutu gwa NWSC e-Participation. Embeera ey'amangu: 0800200977.`,
      xog: `NWSC: Tufunye obubaka bwo "${short}". Ennamba: ${ref}. Bugoberere ku mukutu gwa NWSC e-Participation. Obuzibu obw'amangu: 0800200977.`,
    };
    const sms = SMS_TEXT[lang];
    const tasks: Promise<unknown>[] = [];
    if (phone) tasks.push(sendSms(phone, sms, 'acknowledgement', row.id));
    if (email) {
      const name = contact_name ? escapeHtml(String(contact_name)) : 'Customer';
      tasks.push(sendEmail(
        email,
        `We received your ${kind} — Ref ${ref}`,
        `<p>Dear ${name},</p>
         <p>Thank you for contacting the National Water and Sewerage Corporation, Jinja.
         We have received your ${kind}: <strong>${escapeHtml(String(title).trim())}</strong>.</p>
         <p>Your reference number is <strong style="font-size:18px">${ref}</strong>.
         Use it on the <em>Track My Request</em> page to follow progress.</p>
         <p>For emergencies such as a burst pipe, call our toll-free line 0800-200-977.</p>
         <p>— NWSC Jinja Customer Care</p>`,
        'acknowledgement',
        row.id,
      ));
    }
    const results = await Promise.allSettled(tasks);
    if (results.some((r) => r.status === 'fulfilled' && r.value === true)) {
      await fetch(`${supabaseUrl}/rest/v1/feedback?id=eq.${row.id}`, {
        method: 'PATCH',
        headers: { apikey: serviceRoleKey, Authorization: `Bearer ${serviceRoleKey}`, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        body: JSON.stringify({ acknowledged_at: new Date().toISOString() }),
      });
    }

    return json({ ok: true, reference_no: ref });
  } catch (e) {
    return json({ error: e instanceof Error ? e.message : 'Unknown error' }, 500);
  }
});
